<?php
declare(strict_types=1);
require __DIR__ . '/private/content-store.php';
function out(string $v): string { return htmlspecialchars($v, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8'); }
$section=(string)($_GET['section']??''); $slug=(string)($_GET['slug']??'');
if (!in_array($section,['news','spotlight','rider'],true) || !preg_match('/^[a-z0-9-]{1,180}$/',$slug)) { http_response_code(404); exit('Not found'); }
$q=$pdo->prepare("SELECT * FROM rw_content_items WHERE section=? AND slug=? AND status='published' LIMIT 1"); $q->execute([$section,$slug]); $item=$q->fetch();
if (!$item) { http_response_code(404); exit('Article not found'); }
$item['body_html']=rw_sanitize_html((string)$item['body_html']);
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title><?=out($item['title'])?> | RideWire BMX</title><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="article-content.css"><script src="script.js" defer></script></head><body><header class="site-header"><a class="brand" href="Pages/index.html"><img class="brand-logo" src="assets/ridewire-logo-v5.png" alt="RideWire BMX"></a><nav class="site-nav" id="site-nav"><a href="Pages/index.html">Home</a><a href="Pages/news.html">News</a><a href="Pages/spotlight.html">Spotlight</a><a href="Pages/videos.html">Videos</a><a href="Pages/riders.html">Riders</a><a href="Pages/about.html">About</a></nav></header><main class="content-article"><p class="eyebrow">RideWire BMX / <?=out(strtoupper($section))?><?php if($item['published_at']):?> · <?=out(date('d M Y',strtotime($item['published_at'])))?><?php endif;?></p><h1><?=out($item['title'])?></h1><?php if($item['image']):?><figure><img src="<?=out($item['image'])?>" alt="<?=out($item['image_alt'])?>"><figcaption><?=out($item['image_caption'])?></figcaption></figure><?php endif;?><div class="content-article-body"><?=$item['body_html']?></div><?php if($item['source_url']):?><p class="content-source">Source: <a href="<?=out($item['source_url'])?>" rel="noopener noreferrer" target="_blank">Original source</a></p><?php endif;?></main><footer><a href="Pages/<?=($section==='rider'?'riders':'news')?>.html">Back to <?=($section==='rider'?'Riders':'News')?></a> · RideWire BMX</footer></body></html>
